 return urllib.request.urlopen(req,timeout=60).read().decode('utf8','ignore')
for name,seq in seqs.items():
 t=post({'CMD':'Put','PROGRAM':'blastp','DATABASE':'nr','QUERY':seq,'EXPECT':'1000','HITLIST_SIZE':'20','FORMAT_TYPE':'XML'})
